input.sparql:
PREFIX brick: <http://brickschema.org/schema/brick#>
PREFIX ref: <https://brickschema.org/schema/ontologies/reference#>
SELECT ?sensor ?tsid ?point WHERE {
  ?sensor a brick:ElectricPowerSensor ;
          brick:hasInputSignal ?point ;
          ref:hasTimeseriesId ?tsid .
}

PREFIX brick: <http://brickschema.org/schema/brick#>
PREFIX ref: <https://brickschema.org/schema/ontologies/reference#>
SELECT DISTINCT ?class WHERE {
  ?s ?p ?class .
  FILTER (STRSTARTS(STR(?class), "http://brickschema.org"))
}

